// ดึงค่าข้อความที่บรรจุ JSON String จาก Output ของ Node "Message a model"
const jsonString = $json.content.parts[0].text;

// ทำความสะอาด JSON String: ลบ "json\n(", "\n", ")\n" และ backslash escape
let cleanedString = jsonString
    .trim()
    .replace(/^json\s*\n*\s*\(/i, '') // ลบ 'json(' ที่อาจอยู่ต้นข้อความ
    .replace(/\s*\n*\s*\)\s*\n*$/i, '') // ลบ ')\n' ที่อาจอยู่ท้ายข้อความ
    .replace(/\\"/g, '"') // เปลี่ยน \" เป็น "
    .replace(/\n/g, ''); // ลบ \n

// แปลง JSON String เป็น JavaScript Object
try {
    const parsedJson = JSON.parse(cleanedString);
    return parsedJson;
} catch (e) {
    // หาก Parse ล้มเหลว ให้ใช้ Fallback Logic ค้นหา { }
    try {
        const startIndex = cleanedString.indexOf('{');
        const endIndex = cleanedString.lastIndexOf('}');

        if (startIndex !== -1 && endIndex !== -1) {
            const jsonObjectString = cleanedString.substring(startIndex, endIndex + 1);
            return JSON.parse(jsonObjectString);
        }
    } catch (e2) {
        console.error("Error parsing JSON with fallback:", e2);
    }

    // หากยังล้มเหลว คืนค่า Error
    console.error("Error parsing JSON:", e);
    // สำคัญ: ต้องแน่ใจว่าได้ส่งค่าที่ต้องการ (เช่น FeedbackID) ออกมาในกรณีฉุกเฉิน
    return { error: "Failed to parse JSON", originalText: jsonString };
}

// ดึงข้อมูลอินพุตทั้งหมด
const allInputItems = $input.all();

// 1. ดึงข้อมูล Feedback ต้นฉบับ (ซึ่งคือ Item แรกสุดที่ไม่มี TaskID หรือ TaskID เป็น null/undefined)
// เราจะถือว่า Item ที่ 0 เป็นข้อมูลหลัก (Feedback Data)
const originalData = allInputItems[0].json;

// 2. กรองและเก็บข้อมูล Task ที่รวมจากทุก Item
// โดยกรองเอาเฉพาะ Item ที่มี TaskID ที่ถูกต้องเท่านั้น (เพื่อตัด Item Feedback หลักออก)
const taskList = allInputItems
    .filter(item => item.json.TaskID) // กรองเฉพาะ Item ที่มี TaskID (Tasks)
    .map(item => ({
        TaskID: item.json.TaskID,
        Summary: item.json.Summary,
        Priority: item.json.Priority,
        Status: item.json.Status
    }));

// 3. คืนค่าเป็น Item เดียวที่มีข้อมูล Feedback ต้นฉบับ + Array ของ Tasks
return [
    {
        json: {
            ...originalData, // รวมข้อมูลหลัก เช่น Sentiment, Topic, FeedbackID
            tasks: taskList // Array ของ Task ที่ถูกกรองแล้ว
        }
    }
];

// ดึง Input Data ทั้งหมดออกมาเป็น Array
const allInputItems = $input.all();
// เลือก Item แรกจาก Array นั้น (ซึ่งเป็น Item ที่มี Feedback Data และ Array tasks)
const data = allInputItems[0].json; 

// 1. สร้าง Component สำหรับรายการย่อย (Tasks List)
let taskListComponents = data.tasks.map(task => {
  // กำหนดสีตามสถานะ (Status)
  let statusColor;
  if (task.Status === 'Solved') {
    statusColor = '#4CAF50'; // Green
  } else if (task.Status === 'Pending') {
    statusColor = '#FFC107'; // Yellow/Amber
  } else {
    statusColor = '#F44336'; // Red
  }

  // สร้าง Horizontal Box สำหรับ Task แต่ละรายการ พร้อมจัดการค่าว่าง
  return {
    "type": "box",
    "layout": "horizontal",
    "spacing": "xs",
    "contents": [
      {
        "type": "text",
        // ใช้ || 'N/A' เพื่อป้องกันค่าว่าง
        "text": `ID:${task.TaskID || 'N/A'} (${task.Priority || 'N/A'})`, 
        "size": "sm",
        "flex": 2,
        "weight": "bold",
        "color": "#333333"
      },
      {
        "type": "text",
        // ใช้ || 'No Summary' เพื่อป้องกันค่าว่าง
        "text": `${task.Summary || 'No Summary'}`, 
        "size": "sm",
        "flex": 4,
        "wrap": true,
        "color": "#666666"
      },
      {
        "type": "text",
        // ใช้ || 'Unknown' เพื่อป้องกันค่าว่าง
        "text": `${task.Status || 'Unknown'}`, 
        "size": "sm",
        "flex": 2,
        "align": "end",
        "weight": "bold",
        "color": statusColor
      }
    ]
  };
});

// 2. JSON Template Flex Message 
const flexMessage = {
  "type": "flex",
  "altText": `Feedback ID ${data.FeedbackID || 'N/A'} - ${data.Sentiment || 'N/A'}`,
  "contents": {
    "type": "bubble",
    "styles": {
      "header": {
        "backgroundColor": data.Sentiment === 'Positive' ? '#4CAF50' : data.Sentiment === 'Negative' ? '#F44336' : '#FFC107'
      }
    },
    "header": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        {
          "type": "text",
          "text": "📊 ผลการวิเคราะห์ Feedback ใหม่",
          "weight": "bold",
          "color": "#FFFFFF",
          "size": "md"
        },
        {
          "type": "text",
          "text": `Sentiment: ${data.Sentiment || 'Unknown'}`,
          "weight": "bold",
          "color": "#FFFFFF",
          "size": "xl",
          "margin": "sm"
        }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "spacing": "md",
      "contents": [
        {
          "type": "text",
          "text": `Topic: ${data.Topic || 'N/A'}`,
          "size": "md",
          "color": "#000000"
        },
        { "type": "separator" },
        {
          "type": "box",
          "layout": "vertical",
          "spacing": "sm",
          "contents": [
            {
              "type": "text",
              "text": `Severity (1-5): ${data.Severity || 'N/A'}`,
              "color": data.Severity >= 4 ? '#F44336' : '#FF9800', 
              "weight": "bold"
            },
            {
              "type": "text",
              "text": `Ref ID (Feedback): ${data.FeedbackID || 'N/A'}`,
              "color": "#AAAAAA",
              "size": "sm"
            }
          ]
        },
        { "type": "separator" },
        {
          "type": "box",
          "layout": "vertical",
          "contents": [
            {
              "type": "text",
              "text": `✅ Task ที่ต้องติดตาม (${data.tasks ? data.tasks.length : 0} รายการ):`,
              "weight": "bold",
              "size": "sm",
              "margin": "none"
            },
            // แทรกรายการย่อย
            ...(data.tasks && data.tasks.length > 0 ? taskListComponents : [{
                "type": "text",
                "text": "❌ ไม่มี Task ที่ต้องติดตามเพิ่มเติม",
                "color": "#AAAAAA",
                "size": "sm",
                "margin": "sm"
            }]),
          ]
        }
      ]
    },
    "footer": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        {
          "type": "text",
          "text": `Summary: ${data.Summary || 'No summary provided.'}`,
          "wrap": true,
          "size": "sm"
        }
      ]
    }
  }
};

// คืนค่าเป็น Item ที่มี Flex Message JSON 
return [{ json: { message: flexMessage } }];
